  \coordinate (D) at (0,0);
  \draw[ink,fill=brand!8] (A) -- (B) -- (C) -- (D) -- cycle;
  \node[above left] at (A) {$A$};
  \node[above right] at (B) {$B$};
  \node[below right] at (C) {$C$};
  \node[below left] at (D) {$D$};
  \draw[ink,dashed] (A) -- (C);
  \draw[ink,dashed] (B) -- (D);
  \fill[ink] (1.7,0.85) circle (1.4pt) node[below left=1pt]{$O$};
  \node[brand,font=\scriptsize] at (2.0,1.95) {$>$};
  \node[brand,font=\scriptsize] at (1.4,-0.28) {$>$};
  \node[brand,font=\scriptsize] at (0.15,0.95) {$>>$};
  \node[brand,font=\scriptsize] at (3.25,0.95) {$>>$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình bình hành $ABCD$}
\end{minipage}
\par\vspace{3pt}
- $AB \parallel CD$, $AD \parallel BC$ và $AB = CD$, $AD = BC$. [[br]] - $\widehat{A} = \widehat{C}$, $\widehat{B} = \widehat{D}$; hai góc kề một cạnh bù nhau ($\widehat{A} + \widehat{B} = 180^\circ$). [[br]] - Hai đường chéo cắt nhau tại trung điểm mỗi đường: $OA = OC$, $OB = OD$. [[br]] \textit{Chiều ngược} --- muốn KẾT LUẬN một tứ giác là hình bình hành thì phải chỉ ra đủ hai điều kiện của một trong 5 dấu hiệu.

\par\nopagebreak
\begin{minipage}[t]{0.62\linewidth}\vspace{0pt}
\textbf{Ví dụ mẫu 2.} Cho hình bình hành $ABCD$ có $O$ là giao điểm của hai đường chéo. Trên đoạn $OA$ lấy điểm $M$, trên đoạn $OC$ lấy điểm $N$ sao cho $OM = ON$. Chứng minh tứ giác $BMDN$ là hình bình hành.
\end{minipage}\hfill
\begin{minipage}[t]{0.33\linewidth}\vspace{0pt}
\centering
\adjustbox{max width=\linewidth, max totalheight=2.6cm}{
